const agentData = $input.first().json.output || $input.first().json;

if (!agentData || !agentData.vorschlag) {
  throw new Error('Agent-Output ungueltig oder kein vorschlag-Feld: ' + JSON.stringify(agentData).slice(0, 200));
}

const state = $('Edit Fields2').first().json.state;
const anfrage = state.anfrage;
const pauschale = $('Budgetberechnung').first().json.pauschale || 200;
const guestCount = anfrage.personenanzahl;
const budget = anfrage.budget;

let menuGesamtpreis = 0;

const vorschlag = agentData.vorschlag.map(function(item) {
  const anzahl = item.anzahl || guestCount;
  const gesamtpreis = Math.round(item.preisPerson * anzahl * 100) / 100;
  menuGesamtpreis += gesamtpreis;
  return {
    menuItemId: item.menuItemId,
    name: item.name,
    category: item.category,
    anzahl: anzahl,
    preisPerson: Math.round(item.preisPerson * 100) / 100,
    gesamtpreis: gesamtpreis,
    begruendung: item.begruendung || ''
  };
});

menuGesamtpreis = Math.round(menuGesamtpreis * 100) / 100;
const gesamtpreis = Math.round((menuGesamtpreis + pauschale) * 100) / 100;
const budgetEingehalten = gesamtpreis <= budget;

const proposal = {
  vorschlag, personenanzahl: guestCount, menuGesamtpreis,
  verwaltungspauschale: pauschale, gesamtpreis, budget,
  budgetEingehalten, begruendung: agentData.begruendung || ''
};

const lines = [
  '────────────────────────────────────',
  '  AUSGEWAEHLTE GERICHTE',
  '────────────────────────────────────',
  ''
].concat(vorschlag.map(function(i, idx) {
  return '  ' + (idx + 1) + '. ' + i.name +
    '\n     Kategorie: ' + i.category +
    '\n     Preis/Pers: EUR ' + i.preisPerson.toFixed(2) +
    '\n     Anzahl: ' + i.anzahl + ' Personen' +
    '\n     Gesamt: EUR ' + i.gesamtpreis.toFixed(2) +
    '\n';
})).concat([
  '────────────────────────────────────',
  '  KOSTENUEBERSICHT',
  '────────────────────────────────────',
  '',
  '  Menuepreise gesamt:      EUR ' + menuGesamtpreis.toFixed(2),
  '  Verwaltungspauschale:   EUR ' + pauschale.toFixed(2),
  '  ─────────────────────────────',
  '  GESAMTPREIS:            EUR ' + gesamtpreis.toFixed(2),
  '  Budget:                 EUR ' + budget.toFixed(2),
  '',
  '  Budget eingehalten:  ' + (budgetEingehalten ? 'JA' : 'NEIN - Ueberschreitung!'),
  '',
  '────────────────────────────────────',
  '  BEGRUENDUNG',
  '────────────────────────────────────',
  '',
  '  ' + (proposal.begruendung || '(keine)'),
  '',
  '════════════════════════════════════'
]);

return [{ json: Object.assign({}, proposal, { emailBody: lines.join('\n'), state }) }];

