const ingredients = $input.all().map(item => ({
  id: item.json.Id,
  name: item.json.Name,
  unit: item.json.Unit,
  purchasePricePerUnit: item.json.PurchasePricePerUnit
}));

const ingredientListText = ingredients
  .map(i => `ID ${i.id}: ${i.name} (${i.unit})`)
  .join('\n');

const webhookItem = $('Rechnung empfangen').first();
return [{
  json: { ingredients, ingredientListText },
  binary: webhookItem.binary
}];

const text = $json.content[0].text;
const cleaned = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
const parsed = JSON.parse(cleaned);

return parsed.positions.map((pos, i) => ({
  json: {
    invoice_number: parsed.invoice_number,
    supplier: parsed.supplier,
    invoice_date: parsed.invoice_date,
    ...pos
  },
  pairedItem: { item: 0 }
}));

const dbRow = $json;
const pos = $('Loop: Positionen verarbeiten').first().json;

const unitPrice = pos.unit_price;
const refPrice = parseFloat(dbRow.PurchasePricePerUnit);
const oldCount = parseInt(dbRow.consecutive_over_count, 10);
const newCount = oldCount + 1;
const deviationPercent = ((unitPrice - refPrice) / refPrice) * 100;

return [{ json: {
  matched_ingredient_id: pos.matched_ingredient_id,
  matched_ingredient: pos.matched_ingredient,
  description: pos.description,
  invoice_number: pos.invoice_number,
  supplier: pos.supplier,
  invoice_date: pos.invoice_date,
  unit: pos.unit,
  unit_price: unitPrice,
  ref_price: refPrice,
  consecutive_over_count: oldCount,
  new_count: newCount,
  deviation_percent: deviationPercent
} }];

